	}
	if !reflect.DeepEqual(index.ByHash, byHash) {
		t.Fatalf("by-hash changed after rejected call: got %v want %v", index.ByHash, byHash)
	}
	if index.Tip != tip {
		t.Fatalf("tip changed after rejected call: got %d want %d", index.Tip, tip)
	}
}

