)

// 复现：errors.Join(io.EOF, 存储故障) 与完整快照同批到达时，当前实现把
// errors.Is(err, io.EOF) 当成正常结束，忽略故障并替换主链。
func TestReproJoinEOFWithCompleteSnapshot(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"}, []string{"c"})
	blocks, byHash, tip := snapshot(index)

	// 只有一个区块的合法快照（与现有三区块链不同）。
	oneBlock := `{"version":1,"tip":1,"blocks":[` +
		`{"height":1,"hash":"g1","parent":"g","txs":[]}]}`
